module composite_rank (\n    input clk,\n    input rst_n,\n    input start,\n    input [3:0] n,\n    input [3:0] k,\n    input [7:0] initial_strings [0:7][0:7],\n    input [3:0] initial_lengths [0:7],\n    input [7:0] composite_string [0:63],\n    output reg [31:0] result,\n    output reg done\n);\n\n    // States\n    localparam [3:0] IDLE         = 4'd0;\n    localparam [3:0] SORT         = 4'd1;\n    localparam [3:0] BREAK        = 4'd2;\n    localparam [3:0] COMPUTE_RANK = 4'd3;\n    localparam [3:0] PERM_CALC    = 4'd4;\n    localparam [3:0] DONE_STATE   = 4'd5;\n\n    reg [3:0] state;\n\n    // Sorting registers\n    reg [3:0] i, j;\n    reg [7:0] temp_string [0:7];\n    reg [3:0] temp_length;\n    reg [3:0] temp_original_index;\n\n    // Breaking registers\n    reg [3:0] current_segment;\n    reg [3:0] current_try;\n    reg [5:0] current_position;\n    reg [3:0] seg_indices [0:7];\n\n    // Compute rank registers\n    reg [3:0] current_check_index;\n    reg [31:0] rank;\n    reg [7:0] used;\n    reg [31:0] perm_value;\n    reg [3:0] perm_i;\n    reg [3:0] count;\n\n    // Array storage\n    reg [7:0] sorted_strings [0:7][0:7];\n    reg [3:0] sorted_lengths [0:7];\n    reg [3:0] sorted_original_index [0:7];\n\n    // Segment storage\n    reg [3:0] current_segment_index;\n    reg [7:0] current_segment_string [0:7];\n    reg [3:0] current_segment_length;\n\n    // Comparison flags\n    reg compare_gt;\n    reg match_current_try;\n    reg is_smaller;\n\n    integer idx;\n\n    // Sorting comparison logic\n    always @(*) begin\n        compare_gt = 1'b0;\n        if (j < 4'd7) begin\n            for (idx = 0; idx < 8; idx = idx + 1) begin\n                if (idx < sorted_lengths[j] && idx < sorted_lengths[j+1]) begin\n                    if (sorted_strings[j][idx] > sorted_strings[j+1][idx]) begin\n                        compare_gt = 1'b1;\n                    end else if (sorted_strings[j][idx] < sorted_strings[j+1][idx]) begin\n                        compare_gt = 1'b0;\n                    end\n                end else if (idx < sorted_lengths[j]) begin\n                    compare_gt = 1'b1;\n                end else if (idx < sorted_lengths[j+1]) begin\n                    compare_gt = 1'b0;\n                end\n            end\n        end\n    end\n\n    // Segment matching logic\n    always @(*) begin\n        match_current_try = 1'b1;\n        if (current_try < n) begin\n            for (idx = 0; idx < 8; idx = idx + 1) begin\n                if (idx < initial_lengths[current_try]) begin\n                    if (composite_string[current_position + idx] != initial_strings[current_try][idx]) begin\n                        match_current_try = 1'b0;\n                    end\n                end\n            end\n        end else begin\n            match_current_try = 1'b0;\n        end\n    end\n\n    // Rank comparison logic\n    always @(*) begin\n        is_smaller = 1'b0;\n        if (current_check_index < n) begin\n            for (idx = 0; idx < 8; idx = idx + 1) begin\n                if (idx < sorted_lengths[current_check_index] && idx < current_segment_length) begin\n                    if (sorted_strings[current_check_index][idx] < current_segment_string[idx]) begin\n                        is_smaller = 1'b1;\n                    end else if (sorted_strings[current_check_index][idx] > current_segment_string[idx]) begin\n                        is_smaller = 1'b0;\n                    end\n                end else if (idx < sorted_lengths[current_check_index]) begin\n                    is_smaller = 1'b0;\n                end else if (idx < current_segment_length) begin\n                    is_smaller = 1'b1;\n                end\n            end\n        end\n    end\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            result <= 32'd0;\n            i <= 4'd0;\n            j <= 4'd0;\n            current_segment <= 4'd0;\n            current_try <= 4'd0;\n            current_position <= 6'd0;\n            current_check_index <= 4'd0;\n            rank <= 32'd0;\n            used <= 8'd0;\n            perm_value <= 32'd1;\n            perm_i <= 4'd0;\n            count <= 4'd0;\n            for (integer x = 0; x < 8; x = x + 1) begin\n                seg_indices[x] <= 4'd0;\n                sorted_lengths[x] <= 4'd0;\n                sorted_original_index[x] <= 4'd0;\n                for (integer y = 0; y < 8; y = y + 1) begin\n                    sorted_strings[x][y] <= 8'd0;\n                end\n            end\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        for (integer x = 0; x < 8; x = x + 1) begin\n                            if (x < n) begin\n                                sorted_strings[x] <= initial_strings[x];\n                                sorted_lengths[x] <= initial_lengths[x];\n                                sorted_original_index[x] <= x[3:0];\n                            end else begin\n                                sorted_lengths[x] <= 4'd0;\n                            end\n                        end\n                        state <= SORT;\n                        i <= 4'd0;\n                        j <= 4'd0;\n                    end\n                end\n\n                SORT: begin\n                    if (i < n - 4'd1) begin\n                        if (j < n - 4'd1 - i) begin\n                            if (compare_gt) begin\n                                // Swap operation\n                                temp_string <= sorted_strings[j];\n                                sorted_strings[j] <= sorted_strings[j+1];\n                                sorted_strings[j+1] <= temp_string;\n                                temp_length <= sorted_lengths[j];\n                                sorted_lengths[j] <= sorted_lengths[j+1];\n                                sorted_lengths[j+1] <= temp_length;\n                                temp_original_index <= sorted_original_index[j];\n                                sorted_original_index[j] <= sorted_original_index[j+1];\n                                sorted_original_index[j+1] <= temp_original_index;\n                            end\n                            j <= j + 4'd1;\n                        end else begin\n                            i <= i + 4'd1;\n                            j <= 4'd0;\n                        end\n                    end else begin\n                        state <= BREAK;\n                        current_segment <= 4'd0;\n                        current_try <= 4'd0;\n                        current_position <= 6'd0;\n                    end\n                end\n\n                BREAK: begin\n                    if (current_segment < k) begin\n                        if (current_try < n) begin\n                            if (match_current_try) begin\n                                seg_indices[current_segment] <= current_try;\n                                current_position <= current_position + initial_lengths[current_try];\n                                current_segment <= current_segment + 4'd1;\n                                current_try <= 4'd0;\n                            end else begin\n                                current_try <= current_try + 4'd1;\n                            end\n                        end else begin\n                            state <= DONE_STATE;\n                            result <= 32'hFFFFFFFF;\n                            done <= 1'b1;\n                        end\n                    end else begin\n                        state <= COMPUTE_RANK;\n                        current_segment <= 4'd0;\n                        rank <= 32'd1;\n                        used <= 8'd0;\n                    end\n                end\n\n                COMPUTE_RANK: begin\n                    if (current_segment < k) begin\n                        current_segment_index <= seg_indices[current_segment];\n                        current_segment_string <= initial_strings[seg_indices[current_segment]];\n                        current_segment_length <= initial_lengths[seg_indices[current_segment]];\n                        current_check_index <= 4'd0;\n                        count <= 4'd0;\n                        state <= PERM_CALC;\n                    end else begin\n                        state <= DONE_STATE;\n                        result <= rank;\n                        done <= 1'b1;\n                    end\n                end\n\n                PERM_CALC: begin\n                    if (current_check_index < n) begin\n                        if (used[sorted_original_index[current_check_index]] == 1'b0 && is_smaller) begin\n                            count <= count + 4'd1;\n                        end\n                        current_check_index <= current_check_index + 4'd1;\n                    end else begin\n                        // Calculate permutations\n                        perm_value <= 32'd1;\n                        perm_i <= 4'd0;\n                        state <= 4'd6;  // Additional state for factorial calculation\n                    end\n                end\n\n                4'd6: begin  // Factorial calculation state\n                    if (perm_i < k - current_segment - 4'd1) begin\n                        perm_value <= perm_value * (n - current_segment - 4'd1 - perm_i);\n                        perm_i <= perm_i + 4'd1;\n                    end else begin\n                        rank <= rank + count * perm_value;\n                        used[seg_indices[current_segment]] <= 1'b1;\n                        current_segment <= current_segment + 4'd1;\n                        state <= COMPUTE_RANK;\n                    end\n                end\n\n                DONE_STATE: begin\n                    done <= 1'b1;\n                end\n\n                default: state <= IDLE;\n            endcase\n        end\n    end\n\nendmodule